import React, { useMemo, useState, useEffect } from 'react';
import { parse } from 'marked';
import DOMPurify from 'dompurify';
import type { ChatMessage } from '../types';
import { UserIcon, BotIcon, LinkIcon, DocumentTextIcon, ClipboardIcon, CheckIcon } from './icons';
import BriefingReport from './BriefingReport';
import ImageAnalysisReport from './ImageAnalysisReport';
import LabReport from './LabReport';
import ReasoningIndicator from './ReasoningIndicator'; // New Import
import { isJsonBriefing, isImageAnalysis, isLabReport } from '../utils';
import { ChatMode } from '../types';

const MapPinIcon: React.FC<{className?: string}> = (props) => (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" {...props}>
        <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/>
    </svg>
);

DOMPurify.addHook('afterSanitizeAttributes', (node) => {
    if ('target' in node) {
        node.setAttribute('target', '_blank');
        node.setAttribute('rel', 'noopener noreferrer');
    }
});

interface MessageProps {
    message: ChatMessage;
    isLoading?: boolean;
    isLast?: boolean;
    onImageLoad?: () => void;
}

const Message: React.FC<MessageProps> = ({ message, isLoading, isLast, onImageLoad }) => {
    const isModel = message.role === 'model';
    const [isCopied, setIsCopied] = useState(false);
    const [streamKey, setStreamKey] = useState(0);

    const contentToDisplay = (message.role === 'user' && message.displayContent) ? message.displayContent : message.content;

    const isBriefing = isModel && isJsonBriefing(message.content);
    const isAnalysis = isModel && isImageAnalysis(message.content);
    const isLab = isModel && isLabReport(message.content);

    // Trigger a soft refresh of the animation key whenever content grows
    useEffect(() => {
        if (isModel && isLoading && isLast) {
            setStreamKey(prev => prev + 1);
        }
    }, [message.content, isModel, isLoading, isLast]);

    const isStreamingJson = useMemo(() => {
        if (!isModel || !isLoading || !isLast) return false;
        const content = message.content.trim();
        const hasJsonStart = content.includes('```json') || content.startsWith('{');
        const isComplete = isBriefing || isAnalysis || isLab; 
        return hasJsonStart && !isComplete;
    }, [message.content, isModel, isLoading, isLast, isBriefing, isAnalysis, isLab]);

    const isPlaceholderLoading = useMemo(() => {
        return isModel && isLast && isLoading && !message.content.trim() && !message.filePreview;
    }, [isModel, isLast, isLoading, message.content, message.filePreview]);

    const parsedContent = useMemo(() => {
        if (isPlaceholderLoading || isStreamingJson) return '';
        const html = parse(contentToDisplay, { breaks: true, gfm: true }) as string;
        return DOMPurify.sanitize(html);
    }, [contentToDisplay, isPlaceholderLoading, isStreamingJson]);

    const handleCopy = () => {
        navigator.clipboard.writeText(message.content);
        setIsCopied(true);
        setTimeout(() => setIsCopied(false), 2000);
    };

    const typographyClasses = `
        prose prose-sm dark:prose-invert max-w-none text-slate-700 dark:text-slate-300 leading-relaxed font-sans
        prose-headings:font-bold prose-headings:tracking-tight prose-headings:text-slate-900 dark:prose-headings:text-white
        prose-p:my-2 prose-ul:my-2 prose-li:my-0.5
        prose-strong:font-semibold prose-strong:text-slate-900 dark:prose-strong:text-white
        prose-blockquote:bg-red-50 dark:prose-blockquote:bg-red-900/20 
        prose-blockquote:border-l-4 prose-blockquote:border-red-500 
        prose-blockquote:text-red-800 dark:prose-blockquote:text-red-200 
        prose-blockquote:py-3 prose-blockquote:px-4 prose-blockquote:rounded-r-lg
        prose-blockquote:not-italic prose-blockquote:font-medium prose-blockquote:shadow-sm
        prose-code:font-mono prose-code:text-xs prose-code:bg-slate-100 dark:prose-code:bg-slate-800 prose-code:px-1.5 prose-code:py-0.5 prose-code:rounded prose-code:text-slate-800 dark:prose-code:text-slate-200
        ${isLoading && isLast ? 'animate-soft-stream' : ''}
    `;

    return (
        <div className={`flex items-start gap-2 md:gap-4 ${isModel ? '' : 'flex-row-reverse'} group animate-in fade-in slide-up duration-500`}>
            <div className={`flex-shrink-0 w-8 h-8 md:w-10 md:h-10 rounded-full flex items-center justify-center shadow-md ring-2 ring-white dark:ring-slate-800 ${isModel ? 'bg-gradient-to-br from-medical-500 to-medical-600' : 'bg-slate-200 dark:bg-slate-700'}`}>
                {isModel ? <BotIcon className="w-4 h-4 md:w-6 md:h-6 text-white" /> : <UserIcon className="w-4 h-4 md:w-6 md:h-6 text-slate-500 dark:text-slate-300" />}
            </div>

            <div className={`w-full max-w-full md:max-w-[85%] rounded-2xl p-4 md:p-6 relative shadow-sm border transition-all ${isModel ? 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700' : 'bg-medical-50/50 dark:bg-medical-900/10 border-medical-100 dark:border-medical-900/30'}`}>

                {isModel && !isBriefing && !isAnalysis && !isLab && !isStreamingJson && !isPlaceholderLoading && message.content.trim() && (
                    <button 
                        onClick={handleCopy}
                        className="absolute top-3 right-3 p-1.5 rounded-lg text-slate-400 hover:text-medical-600 hover:bg-slate-50 dark:hover:bg-slate-700 opacity-0 group-hover:opacity-100 transition-all"
                        title="Copy"
                    >
                        {isCopied ? <CheckIcon className="w-3.5 h-3.5 text-green-500" /> : <ClipboardIcon className="w-3.5 h-3.5" />}
                    </button>
                )}

                {message.filePreview && (
                    <div className="mb-4">
                        {message.filePreview.type.startsWith('image/') && message.filePreview.url ? (
                            <div className="relative group inline-block rounded-lg overflow-hidden border border-slate-200 dark:border-slate-700 shadow-sm">
                                <img 
                                    src={message.filePreview.url} 
                                    alt={message.filePreview.name} 
                                    onLoad={onImageLoad}
                                    className="max-w-full md:max-w-sm object-cover block" 
                                />
                                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors"></div>
                            </div>
                        ) : (
                             <div className="flex items-center gap-3 p-3 rounded-lg bg-white dark:bg-slate-700/50 border border-slate-200 dark:border-slate-600 w-fit shadow-sm">
                                <div className="p-2 bg-slate-100 dark:bg-slate-600 rounded-md">
                                    <DocumentTextIcon className="w-6 h-6 text-slate-500 dark:text-slate-400" />
                                </div>
                                <div>
                                    <p className="font-medium text-sm text-slate-700 dark:text-slate-200 line-clamp-1">{message.filePreview.name}</p>
                                    <p className="text-xs text-slate-500 dark:text-slate-400 uppercase tracking-wider font-semibold">{message.filePreview.type.split('/')[1] || 'FILE'}</p>
                                 </div>
                            </div>
                        )}
                    </div>
                )}

                {isBriefing ? (
                    <BriefingReport content={message.content} />
                ) : isAnalysis ? (
                    <ImageAnalysisReport content={message.content} />
                ) : isLab ? (
                    <LabReport content={message.content} />
                ) : isStreamingJson ? (
                     <div className="flex flex-col gap-4 p-2 w-full min-w-[300px]">
                        <div className="flex items-center gap-3 text-medical-600 dark:text-medical-400">
                            <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin"></div>
                            <span className="font-mono text-sm font-medium tracking-wide animate-pulse">ANALYZING CLINICAL DATA...</span>
                        </div>
                        <div className="space-y-3">
                            <div className="h-4 shimmer-bg animate-shimmer rounded w-3/4 opacity-40"></div>
                            <div className="h-4 shimmer-bg animate-shimmer rounded w-1/2 opacity-40"></div>
                            <div className="h-32 bg-slate-50 dark:bg-slate-800/50 rounded-lg w-full mt-2 border border-dashed border-slate-300 dark:border-slate-600 flex items-center justify-center">
                                <span className="text-xs font-mono text-slate-400 animate-pulse">PARSING SCHEMA...</span>
                            </div>
                        </div>
                    </div>
                ) : isPlaceholderLoading ? (
                    <ReasoningIndicator mode={ChatMode.Auto} />
                ) : (
                    <div 
                        key={streamKey} 
                        className={typographyClasses} 
                        dangerouslySetInnerHTML={{ __html: parsedContent }}
                    ></div>
                )}

                {message.sources && message.sources.length > 0 && (
                    <div className="mt-5 pt-4 border-t border-slate-100 dark:border-slate-700/50 animate-in fade-in duration-700">
                        <div className="flex items-center gap-2 mb-3">
                            <div className="w-1 h-4 bg-medical-500 rounded-full"></div>
                            <h4 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">References & Locations</h4>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            {message.sources.map((source, i) => {
                                if (source.web) {
                                    return (
                                        <a key={i} href={source.web.uri} target="_blank" rel="noopener noreferrer"
                                            className="flex items-center gap-1.5 bg-slate-50 dark:bg-slate-700/50 hover:bg-medical-50 dark:hover:bg-slate-600 border border-slate-200 dark:border-slate-600 hover:border-medical-200 px-3 py-1.5 rounded-md text-xs font-medium text-slate-600 dark:text-slate-300 transition-all shadow-sm hover:shadow"
                                        >
                                            <LinkIcon className="w-3 h-3 flex-shrink-0 text-medical-500" />
                                            <span className="truncate max-w-[200px]">{source.web.title || new URL(source.web.uri).hostname}</span>
                                        </a>
                                    );
                                }
                                if (source.maps) {
                                    return (
                                        <a key={i} href={source.maps.uri} target="_blank" rel="noopener noreferrer"
                                            className="flex items-center gap-1.5 bg-green-50 dark:bg-green-900/20 hover:bg-green-100 dark:hover:bg-green-900/40 border border-green-200 dark:border-green-800 hover:border-green-300 px-3 py-1.5 rounded-md text-xs font-medium text-green-800 dark:text-green-300 transition-all shadow-sm hover:shadow"
                                        >
                                            <MapPinIcon className="w-3 h-3 flex-shrink-0 text-green-600 dark:text-green-400" />
                                            <span className="truncate max-w-[200px]">{source.maps.title}</span>
                                        </a>
                                    );
                                }
                                return null;
                            })}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Message;

import React, { useState, useMemo, useCallback } from 'react';
import { parse } from 'marked';
import DOMPurify from 'dompurify';
import { AlertTriangleIcon, UsersIcon, PillIcon, ListChecksIcon, PhoneForwardedIcon, ClockIcon, DownloadIcon, ClipboardCheckIcon, ClipboardIcon } from './icons';
import { exportBriefingToPdf } from '../services/exportService';
import { parseJsonSafe } from '../utils';

interface BriefingReportProps {
    content: string; // Expects a JSON string
}

interface ParsedSection {
    title: string;
    items: string[];
}

interface ParsedBriefing {
    briefingTitle: string;
    sections: ParsedSection[];
}

const SECTION_CONFIG: Record<string, { icon: React.FC<{className: string}>; color: string }> = {
    'PRIORITY CASES': { icon: AlertTriangleIcon, color: 'red' },
    'CRITICAL ALERTS': { icon: AlertTriangleIcon, color: 'red' },
    'PATIENT OVERVIEW': { icon: UsersIcon, color: 'blue' },
    'MEDICATIONS & TREATMENTS': { icon: PillIcon, color: 'indigo' },
    'FOLLOW-UP REQUIRED': { icon: ListChecksIcon, color: 'amber' },
    'HANDOFF NOTES': { icon: PhoneForwardedIcon, color: 'slate' },
    'SHIFT TIMELINE': { icon: ClockIcon, color: 'slate' },
};

const BriefingReport: React.FC<BriefingReportProps> = ({ content }) => {
    const [isCopied, setIsCopied] = useState(false);
    const [isExporting, setIsExporting] = useState(false);
    const [checkedItems, setCheckedItems] = useState<Record<string, boolean>>({});

    const parsedBriefing = useMemo<ParsedBriefing | null>(() => {
        return parseJsonSafe<ParsedBriefing>(content);
    }, [content]);

    const handleCopy = useCallback(() => {
        if (!parsedBriefing) return;

        let textToCopy = `${parsedBriefing.briefingTitle}\n\n`;
        parsedBriefing.sections.forEach(section => {
            textToCopy += `**${section.title}**\n`;
            section.items.forEach(item => { textToCopy += `- ${item}\n`; });
            textToCopy += '\n';
        });

        navigator.clipboard.writeText(textToCopy);
        setIsCopied(true);
        setTimeout(() => setIsCopied(false), 2000);
    }, [parsedBriefing]);

    const handleExportPdf = useCallback(async () => {
        if (!parsedBriefing || isExporting) return;

        setIsExporting(true);
        try {
            await exportBriefingToPdf(parsedBriefing);
        } catch (error) {
            console.error("Error exporting PDF:", error);
            alert("Sorry, there was an error exporting the PDF. Please try again.");
        } finally {
            setIsExporting(false);
        }
    }, [parsedBriefing, isExporting]);

    const toggleItem = (sectionIndex: number, itemIndex: number) => {
        const key = `${sectionIndex}-${itemIndex}`;
        setCheckedItems(prev => ({
            ...prev,
            [key]: !prev[key]
        }));
    };

    const renderMarkdownItem = (item: string) => {
        const html = parse(item, { breaks: false, gfm: true }) as string;
        const sanitized = DOMPurify.sanitize(html, { ADD_ATTR: ['target'] });
        return { __html: sanitized };
    };

    if (!parsedBriefing) {
        const rawHtml = parse(content, { breaks: true, gfm: true }) as string;
        const sanitizedRaw = DOMPurify.sanitize(rawHtml);

        return (
            <div className="space-y-2">
                <div className="p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-700 rounded-lg flex items-start gap-2">
                    <AlertTriangleIcon className="w-5 h-5 text-amber-600 dark:text-amber-400 flex-shrink-0 mt-0.5" />
                    <p className="text-sm text-amber-700 dark:text-amber-200">
                        <strong>Formatting Error:</strong> The briefing could not be structured automatically. Displaying raw output below.
                    </p>
                </div>
                <div className="prose prose-sm dark:prose-invert max-w-none p-2" dangerouslySetInnerHTML={{ __html: sanitizedRaw }} />
            </div>
        );
    }

    return (
        <div className="bg-slate-50 dark:bg-slate-900/50 -m-4 p-4 rounded-xl">
            <div className="flex flex-col sm:flex-row sm:justify-between sm:items-start mb-4 gap-3">
                 <h2 className="text-lg font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2">
                    <span className="text-2xl">📋</span>
                    <span>{parsedBriefing.briefingTitle}</span>
                </h2>
                <div className="flex gap-2 flex-shrink-0 self-end sm:self-auto">
                    <button onClick={handleCopy} disabled={isExporting} className="flex items-center gap-1.5 text-xs font-semibold px-2.5 py-1.5 rounded-md bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 text-slate-600 dark:text-slate-200 transition-colors disabled:opacity-50">
                        {isCopied ? <ClipboardCheckIcon className="w-4 h-4 text-green-500" /> : <ClipboardIcon className="w-4 h-4" />}
                        {isCopied ? 'Copied!' : 'Copy'}
                    </button>
                    <button onClick={handleExportPdf} disabled={isExporting} className="flex items-center gap-1.5 text-xs font-semibold px-2.5 py-1.5 rounded-md bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 text-slate-600 dark:text-slate-200 transition-colors disabled:opacity-50">
                        {isExporting ? <div className="w-4 h-4 border-2 border-slate-500 border-t-transparent rounded-full animate-spin"></div> : <DownloadIcon className="w-4 h-4" />}
                        {isExporting ? 'Exporting...' : 'Export PDF'}
                    </button>
                </div>
            </div>

            <div className="space-y-4">
                {parsedBriefing.sections.map((section, sIdx) => {
                    if (!section.items || section.items.length === 0) return null;
                    const config = SECTION_CONFIG[section.title] || { icon: ListChecksIcon, color: 'slate' };
                    const Icon = config.icon;
                    const isCritical = config.color === 'red';

                    return (
                        <div key={section.title} className={`rounded-lg p-3 ${isCritical ? 'bg-red-100/50 dark:bg-red-900/20' : 'bg-slate-100 dark:bg-slate-700/50'}`}>
                            <h3 className={`flex items-center gap-2 font-bold mb-2 text-sm ${isCritical ? 'text-red-700 dark:text-red-300' : 'text-slate-700 dark:text-slate-200'}`}>
                                <Icon className="w-5 h-5" />
                                <span>{section.title}</span>
                            </h3>
                            <ul className="space-y-1.5 pl-1">
                                {section.items.map((item, iIdx) => {
                                    const isChecked = checkedItems[`${sIdx}-${iIdx}`];
                                    return (
                                        <li 
                                            key={iIdx} 
                                            onClick={() => toggleItem(sIdx, iIdx)}
                                            className={`group flex items-start gap-3 p-2 rounded-md cursor-pointer transition-colors ${
                                                isChecked 
                                                ? 'bg-slate-200/50 dark:bg-slate-800/50 opacity-60' 
                                                : 'hover:bg-white/60 dark:hover:bg-slate-600/30'
                                            }`}
                                        >
                                            <div className={`mt-0.5 w-4 h-4 rounded border flex items-center justify-center flex-shrink-0 transition-colors ${
                                                isChecked
                                                ? 'bg-slate-500 border-slate-500' 
                                                : 'border-slate-400 bg-white dark:bg-slate-800 dark:border-slate-500'
                                            }`}>
                                                {isChecked && <svg className="w-3 h-3 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><polyline points="20 6 9 17 4 12"></polyline></svg>}
                                            </div>
                                            <div 
                                                className={`text-sm leading-relaxed text-slate-700 dark:text-slate-300 [&>p]:inline ${isChecked ? 'line-through text-slate-500 dark:text-slate-500' : ''}`}
                                                dangerouslySetInnerHTML={renderMarkdownItem(item)}
                                            />
                                        </li>
                                    );
                                })}
                            </ul>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

export default BriefingReport;

import React, { useMemo } from 'react';
import { BeakerIcon, UserIcon, CalendarIcon, AlertTriangleIcon } from './icons';
import { parseJsonSafe } from '../utils';

interface LabResult {
    testName: string;
    value: string;
    units: string;
    refRange: string;
    flag: 'Normal' | 'High' | 'Low' | 'Critical' | 'Abnormal';
}

interface ParsedLabReport {
    reportType: string;
    patient?: string;
    date?: string;
    labs: LabResult[];
    interpretation?: string;
}

interface LabReportProps {
    content: string;
}

const getFlagColor = (flag: string) => {
    const f = flag.toLowerCase();
    if (f.includes('critical')) return 'bg-red-500 text-white animate-pulse shadow-md shadow-red-500/20';
    if (f.includes('high')) return 'bg-amber-100 text-amber-800 border border-amber-200';
    if (f.includes('low')) return 'bg-blue-100 text-blue-800 border border-blue-200';
    if (f.includes('abnormal')) return 'bg-amber-100 text-amber-800 border border-amber-200';
    return 'bg-slate-100 text-slate-600 border border-slate-200';
};

// Heuristic to visually plot a value against a range
const RangeVisualizer: React.FC<{ value: string; range: string }> = ({ value, range }) => {
    try {
        const val = parseFloat(value.replace(/[^0-9.-]/g, ''));
        const rangeMatch = range.match(/([\d.]+)\s*-\s*([\d.]+)/);

        if (isNaN(val) || !rangeMatch) return null;

        const min = parseFloat(rangeMatch[1]);
        const max = parseFloat(rangeMatch[2]);
        const spread = max - min;
        const totalMin = min - (spread * 0.5); // Extend bar 50% below min
        const totalMax = max + (spread * 0.5); // Extend bar 50% above max
        const totalSpread = totalMax - totalMin;

        // Calculate percentages
        const leftPct = ((val - totalMin) / totalSpread) * 100;
        const startRangePct = ((min - totalMin) / totalSpread) * 100;
        const rangeWidthPct = (spread / totalSpread) * 100;

        const clampedPos = Math.max(0, Math.min(100, leftPct));

        return (
            <div className="w-24 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full relative mt-1.5 overflow-hidden">
                {/* Reference Range Zone */}
                <div 
                    className="absolute top-0 bottom-0 bg-slate-300 dark:bg-slate-600 opacity-50" 
                    style={{ left: `${startRangePct}%`, width: `${rangeWidthPct}%` }}
                />

                {/* Value Marker */}
                <div 
                    className={`absolute top-0 bottom-0 w-2 h-2 -ml-1 rounded-full border border-white shadow-sm z-10 ${
                        val < min ? 'bg-blue-500' : val > max ? 'bg-amber-500' : 'bg-green-500'
                    }`}
                    style={{ left: `${clampedPos}%`, top: '-1px' }}
                />
            </div>
        );
    } catch(e) {
        return null;
    }
};

