interface MessageListProps {
    messages: ChatMessage[];
    isLoading: boolean;
    isLive?: boolean;
    liveTranscript?: LiveTranscript;
    onViewImage?: (src: string, alt: string) => void;
}

const MessageList: React.FC<MessageListProps> = ({ messages, isLoading, isLive, liveTranscript, onViewImage }) => {
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [isAtBottom, setIsAtBottom] = useState(true);

    const handleScroll = () => {
        if (!containerRef.current) return;
        const { scrollTop, scrollHeight, clientHeight } = containerRef.current;
        const atBottom = scrollHeight - scrollTop - clientHeight < 50;
        setIsAtBottom(atBottom);
    };

    const scrollToBottom = useCallback((behavior: ScrollBehavior = 'smooth') => {
        messagesEndRef.current?.scrollIntoView({ behavior });
    }, []);

    useEffect(() => {
        if (isAtBottom) {
            scrollToBottom(isLoading ? 'auto' : 'smooth');
        }
    }, [messages, isLoading, liveTranscript, isAtBottom, scrollToBottom]);

    const handleImageLoad = useCallback(() => {
        if (isAtBottom) {
            scrollToBottom('auto');
        }
    }, [isAtBottom, scrollToBottom]);

    if (messages.length === 0 && !isLive) {
        return <WelcomeScreen />;
    }

    return (
        <main 
            className="flex-1 overflow-y-auto p-2 md:p-6" 
            ref={containerRef}
            onScroll={handleScroll}
        >
            <div className="max-w-3xl mx-auto space-y-4 md:space-y-6 pb-4">
                {messages.map((msg, index) => (
                    <Message 
                        key={index} 
                        message={msg} 
                        isLoading={isLoading} 
                        isLast={index === messages.length - 1}
                        onImageLoad={handleImageLoad}
                        onViewImage={onViewImage}
                    />
                ))}

                {isLive && liveTranscript && <LiveTranscriptDisplay transcript={liveTranscript} />}

                <div ref={messagesEndRef} />
            </div>
        </main>
    );
};

export default MessageList;

import React, { useMemo, useState, useEffect } from 'react';
import { parse } from 'marked';
import DOMPurify from 'dompurify';
import type { ChatMessage } from '../types';
import { UserIcon, BotIcon, LinkIcon, DocumentTextIcon, ClipboardIcon, CheckIcon, ImageIcon } from './icons';
import BriefingReport from './BriefingReport';
import ImageAnalysisReport from './ImageAnalysisReport';
import LabReport from './LabReport';
import ReasoningIndicator from './ReasoningIndicator'; 
import { isJsonBriefing, isImageAnalysis, isLabReport } from '../utils';
import { ChatMode } from '../types';

const MapPinIcon: React.FC<{className?: string}> = (props) => (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" {...props}>
        <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/>
    </svg>
);

DOMPurify.addHook('afterSanitizeAttributes', (node) => {
    if ('target' in node) {
        node.setAttribute('target', '_blank');
        node.setAttribute('rel', 'noopener noreferrer');
    }
});

interface MessageProps {
    message: ChatMessage;
    isLoading?: boolean;
    isLast?: boolean;
    onImageLoad?: () => void;
    onViewImage?: (src: string, alt: string) => void;
}

const Message: React.FC<MessageProps> = ({ message, isLoading, isLast, onImageLoad, onViewImage }) => {
    const isModel = message.role === 'model';
    const [isCopied, setIsCopied] = useState(false);
    const [streamKey, setStreamKey] = useState(0);

    const contentToDisplay = (message.role === 'user' && message.displayContent) ? message.displayContent : message.content;

    const isBriefing = isModel && isJsonBriefing(message.content);
    const isAnalysis = isModel && isImageAnalysis(message.content);
    const isLab = isModel && isLabReport(message.content);

    // Trigger a soft refresh of the animation key whenever content grows
    useEffect(() => {
        if (isModel && isLoading && isLast) {
            setStreamKey(prev => prev + 1);
        }
    }, [message.content, isModel, isLoading, isLast]);

    const isStreamingJson = useMemo(() => {
        if (!isModel || !isLoading || !isLast) return false;
        const content = message.content.trim();
        const hasJsonStart = content.includes('```json') || content.startsWith('{');
        const isComplete = isBriefing || isAnalysis || isLab; 
        return hasJsonStart && !isComplete;
    }, [message.content, isModel, isLoading, isLast, isBriefing, isAnalysis, isLab]);

    const isPlaceholderLoading = useMemo(() => {
        return isModel && isLast && isLoading && !message.content.trim() && !message.filePreview;
    }, [isModel, isLast, isLoading, message.content, message.filePreview]);

    const parsedContent = useMemo(() => {
        if (isPlaceholderLoading || isStreamingJson) return '';
        const html = parse(contentToDisplay, { breaks: true, gfm: true }) as string;
        return DOMPurify.sanitize(html);
    }, [contentToDisplay, isPlaceholderLoading, isStreamingJson]);

    const handleCopy = () => {
        navigator.clipboard.writeText(message.content);
        setIsCopied(true);
        setTimeout(() => setIsCopied(false), 2000);
    };

    const typographyClasses = `
        prose prose-sm dark:prose-invert max-w-none text-slate-700 dark:text-slate-300 leading-relaxed font-sans
        prose-headings:font-bold prose-headings:tracking-tight prose-headings:text-slate-900 dark:prose-headings:text-white
        prose-p:my-2 prose-ul:my-2 prose-li:my-0.5
        prose-strong:font-semibold prose-strong:text-slate-900 dark:prose-strong:text-white
        prose-blockquote:bg-red-50 dark:prose-blockquote:bg-red-900/20 
        prose-blockquote:border-l-4 prose-blockquote:border-red-500 
        prose-blockquote:text-red-800 dark:prose-blockquote:text-red-200 
        prose-blockquote:py-3 prose-blockquote:px-4 prose-blockquote:rounded-r-lg
        prose-blockquote:not-italic prose-blockquote:font-medium prose-blockquote:shadow-sm
        prose-code:font-mono prose-code:text-xs prose-code:bg-slate-100 dark:prose-code:bg-slate-800 prose-code:px-1.5 prose-code:py-0.5 prose-code:rounded prose-code:text-slate-800 dark:prose-code:text-slate-200
        ${isLoading && isLast ? 'animate-soft-stream' : ''}
    `;

    return (
        <div className={`flex items-start gap-2 md:gap-4 ${isModel ? '' : 'flex-row-reverse'} group animate-in fade-in slide-up duration-500`}>
            <div className={`flex-shrink-0 w-8 h-8 md:w-10 md:h-10 rounded-full flex items-center justify-center shadow-md ring-2 ring-white dark:ring-slate-800 ${isModel ? 'bg-gradient-to-br from-medical-500 to-medical-600' : 'bg-slate-200 dark:bg-slate-700'}`}>
                {isModel ? <BotIcon className="w-4 h-4 md:w-6 md:h-6 text-white" /> : <UserIcon className="w-4 h-4 md:w-6 md:h-6 text-slate-500 dark:text-slate-300" />}
            </div>

            <div className={`w-full max-w-full md:max-w-[85%] rounded-2xl p-4 md:p-6 relative shadow-sm border transition-all ${isModel ? 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700' : 'bg-medical-50/50 dark:bg-medical-900/10 border-medical-100 dark:border-medical-900/30'}`}>

                {isModel && !isBriefing && !isAnalysis && !isLab && !isStreamingJson && !isPlaceholderLoading && message.content.trim() && (
                    <button 
                        onClick={handleCopy}
                        className="absolute top-3 right-3 p-1.5 rounded-lg text-slate-400 hover:text-medical-600 hover:bg-slate-50 dark:hover:bg-slate-700 opacity-0 group-hover:opacity-100 transition-all"
                        title="Copy"
                    >
                        {isCopied ? <CheckIcon className="w-3.5 h-3.5 text-green-500" /> : <ClipboardIcon className="w-3.5 h-3.5" />}
                    </button>
                )}

                {message.filePreview && (
                    <div className="mb-4">
                        {message.filePreview.type.startsWith('image/') && message.filePreview.url ? (
                            <button 
                                onClick={() => onViewImage?.(message.filePreview!.url!, message.filePreview!.name)}
                                className="relative group inline-block rounded-lg overflow-hidden border border-slate-200 dark:border-slate-700 shadow-sm cursor-zoom-in text-left"
                            >
                                <img 
                                    src={message.filePreview.url} 
                                    alt={message.filePreview.name} 
                                    onLoad={onImageLoad}
                                    className="max-w-full md:max-w-sm object-cover block" 
                                />
                                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors flex items-center justify-center">
                                    <div className="bg-black/50 text-white text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity flex items-center gap-1 backdrop-blur-sm">
                                        <ImageIcon className="w-3 h-3" />
                                        <span>Click to Enlarge</span>
                                    </div>
                                </div>
                            </button>
                        ) : (
                             <div className="flex items-center gap-3 p-3 rounded-lg bg-white dark:bg-slate-700/50 border border-slate-200 dark:border-slate-600 w-fit shadow-sm">
                                <div className="p-2 bg-slate-100 dark:bg-slate-600 rounded-md">
                                    <DocumentTextIcon className="w-6 h-6 text-slate-500 dark:text-slate-400" />
                                </div>
                                <div>
                                    <p className="font-medium text-sm text-slate-700 dark:text-slate-200 line-clamp-1">{message.filePreview.name}</p>
                                    <p className="text-xs text-slate-500 dark:text-slate-400 uppercase tracking-wider font-semibold">{message.filePreview.type.split('/')[1] || 'FILE'}</p>
                                 </div>
                            </div>
                        )}
                    </div>
                )}

                {isBriefing ? (
                    <BriefingReport content={message.content} />
                ) : isAnalysis ? (
                    <ImageAnalysisReport content={message.content} />
                ) : isLab ? (
                    <LabReport content={message.content} />
                ) : isStreamingJson ? (
                     <div className="flex flex-col gap-4 p-2 w-full min-w-[300px]">
                        <div className="flex items-center gap-3 text-medical-600 dark:text-medical-400">
                            <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin"></div>
                            <span className="font-mono text-sm font-medium tracking-wide animate-pulse">ANALYZING CLINICAL DATA...</span>
                        </div>
                        <div className="space-y-3">
                            <div className="h-4 shimmer-bg animate-shimmer rounded w-3/4 opacity-40"></div>
                            <div className="h-4 shimmer-bg animate-shimmer rounded w-1/2 opacity-40"></div>
                            <div className="h-32 bg-slate-50 dark:bg-slate-800/50 rounded-lg w-full mt-2 border border-dashed border-slate-300 dark:border-slate-600 flex items-center justify-center">
                                <span className="text-xs font-mono text-slate-400 animate-pulse">PARSING SCHEMA...</span>
                            </div>
                        </div>
                    </div>
                ) : isPlaceholderLoading ? (
                    <ReasoningIndicator mode={ChatMode.Auto} />
                ) : (
                    <div 
                        key={streamKey} 
                        className={typographyClasses} 
                        dangerouslySetInnerHTML={{ __html: parsedContent }}
                    ></div>
                )}

                {message.sources && message.sources.length > 0 && (
                    <div className="mt-5 pt-4 border-t border-slate-100 dark:border-slate-700/50 animate-in fade-in duration-700">
                        <div className="flex items-center gap-2 mb-3">
                            <div className="w-1 h-4 bg-medical-500 rounded-full"></div>
                            <h4 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">References & Locations</h4>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            {message.sources.map((source, i) => {
                                if (source.web) {
                                    return (
                                        <a key={i} href={source.web.uri} target="_blank" rel="noopener noreferrer"
                                            className="flex items-center gap-1.5 bg-slate-50 dark:bg-slate-700/50 hover:bg-medical-50 dark:hover:bg-slate-600 border border-slate-200 dark:border-slate-600 hover:border-medical-200 px-3 py-1.5 rounded-md text-xs font-medium text-slate-600 dark:text-slate-300 transition-all shadow-sm hover:shadow"
                                        >
                                            <LinkIcon className="w-3 h-3 flex-shrink-0 text-medical-500" />
                                            <span className="truncate max-w-[200px]">{source.web.title || new URL(source.web.uri).hostname}</span>
                                        </a>
                                    );
                                }
                                if (source.maps) {
                                    return (
                                        <a key={i} href={source.maps.uri} target="_blank" rel="noopener noreferrer"
                                            className="flex items-center gap-1.5 bg-green-50 dark:bg-green-900/20 hover:bg-green-100 dark:hover:bg-green-900/40 border border-green-200 dark:border-green-800 hover:border-green-300 px-3 py-1.5 rounded-md text-xs font-medium text-green-800 dark:text-green-300 transition-all shadow-sm hover:shadow"
                                        >
                                            <MapPinIcon className="w-3 h-3 flex-shrink-0 text-green-600 dark:text-green-400" />
                                            <span className="truncate max-w-[200px]">{source.maps.title}</span>
                                        </a>
                                    );
                                }
                                return null;
                            })}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Message;

import React, { useState, useRef, useCallback, ChangeEvent, KeyboardEvent, useEffect, useLayoutEffect } from 'react';
import type { UploadedFile, ChatMode } from '../types';
import { ChatMode as ChatModeEnum } from '../types';
import { PaperclipIcon, SendIcon, XCircleIcon, BriefingIcon, UserIcon, DrugsIcon, DownloadIcon, DocumentTextIcon, MicrophoneIcon, CameraIcon, LiveIcon, StopIcon } from './icons';

interface InputBarProps {
    onSend: (prompt: string) => void;
    onClearFile: () => void;
    setUploadedFile: (file: UploadedFile) => void;
    isLoading: boolean;
    currentMode: ChatMode;
    uploadedFile: UploadedFile | null;
    toggleLiveSession: () => void;
    isLiveSessionActive: boolean;
    onStop?: () => void;
}

declare global {
    interface Window {
        SpeechRecognition: any;
        webkitSpeechRecognition: any;
    }
}

const QUICK_COMMANDS = [
  { command: '/brief', description: 'Shift briefing', icon: BriefingIcon },
  { command: '/patient ', description: 'Patient summary', icon: UserIcon },
  { command: '/drugs ', description: 'Check drugs', icon: DrugsIcon },
  { command: '/export', description: 'Export PDF', icon: DownloadIcon },
];

const InputBar: React.FC<InputBarProps> = ({ onSend, onClearFile, setUploadedFile, isLoading, currentMode, uploadedFile, toggleLiveSession, isLiveSessionActive, onStop }) => {
    const [prompt, setPrompt] = useState('');
    const [showCommands, setShowCommands] = useState(false);
    const [isListening, setIsListening] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const cameraInputRef = useRef<HTMLInputElement>(null);
    const textareaRef = useRef<HTMLTextAreaElement>(null);
    const recognitionRef = useRef<any>(null);

    useEffect(() => {
        let activeUrl = uploadedFile?.url;
        return () => {
            if (activeUrl) {
                setTimeout(() => { URL.revokeObjectURL(activeUrl!); }, 1000);
            }
        };
    }, [uploadedFile]);

    // Ensure speech recognition stops if component unmounts
    useEffect(() => {
        return () => {
            if (recognitionRef.current) {
                try { recognitionRef.current.stop(); } catch(e) {}
            }
        };
    }, []);

    const handleFileChange = (event: ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (file) {
            if (file.size > 4 * 1024 * 1024) {
                alert("File is too large. Please select a file smaller than 4MB.");
                return;
            }
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64 = (reader.result as string).split(',')[1];
                const uploadPayload: UploadedFile = { file, base64, type: file.type };
                if (file.type.startsWith('image/')) {
                    uploadPayload.url = URL.createObjectURL(file);
                }
                setUploadedFile(uploadPayload);
            };
            reader.readAsDataURL(file);
        }
        if (event.target) event.target.value = '';
    };

    const handleSendClick = useCallback(() => {
        const canSend = !isLoading || isLiveSessionActive;
        if (canSend) {
            if (recognitionRef.current) {
                recognitionRef.current.onresult = null;
                recognitionRef.current.onend = null; 
                try { recognitionRef.current.stop(); } catch(e) {}
                setIsListening(false);
            }
            onSend(prompt);
            setPrompt('');
            setShowCommands(false);
        }
    }, [isLoading, isLiveSessionActive, onSend, prompt]);

    const handleCommandSelect = (command: string) => {
        setPrompt(command);
        setShowCommands(false);
        setTimeout(() => textareaRef.current?.focus(), 0);
    };

    const handleKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
        if (event.key === 'Enter' && !event.shiftKey) {
            event.preventDefault();
            handleSendClick();
        }
    };

    const resizeTextarea = () => {
        const textarea = textareaRef.current;
        if (textarea) {
            // Reset to auto to correctly measure the new content height
            textarea.style.height = 'auto';

            // FIX: If empty, remove inline style so CSS classes (padding) control the height.
            // This prevents the "21px" issue where scrollHeight excludes padding in some states.
            if (prompt === '') {
                textarea.style.height = '';
                return;
            }

            const scrollHeight = textarea.scrollHeight;
            textarea.style.height = `${Math.min(scrollHeight, 150)}px`;
        }
    };

    const handleTextareaInput = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        const value = e.target.value;
        setPrompt(value);
        setShowCommands(value.trim() === '/' || value.endsWith(' /'));
    };

    const handleSpeechToText = useCallback(() => {
        if (isListening) {
            if (recognitionRef.current) recognitionRef.current.stop();
            return;
        }

        const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
        if (!SpeechRecognition) {
            alert("Speech recognition not supported in this browser.");
            return;
        }

        const recognition = new SpeechRecognition();
        recognition.continuous = true;
        recognition.interimResults = true;
        recognition.lang = 'en-US';
        recognitionRef.current = recognition;

        recognition.onstart = () => setIsListening(true);
        recognition.onend = () => setIsListening(false);
        recognition.onerror = (event: any) => {
            console.error('Speech error:', event.error);
            setIsListening(false);

            // Specific error handling for user feedback
            if (event.error === 'not-allowed' || event.error === 'service-not-allowed') {
                alert("Microphone access denied. Please allow microphone permission in your browser settings.");
            } else if (event.error === 'no-speech') {
                // Usually ignore no-speech, but if it persists it might be hardware
            } else if (event.error === 'audio-capture') {
                alert("No microphone was found. Ensure your microphone is connected.");
            } else if (event.error === 'network') {
                alert("Network error preventing speech recognition.");
            }
        };

        let finalTranscript = prompt ? prompt + ' ' : '';

        recognition.onresult = (event: any) => {
            let interimTranscript = '';
            for (let i = event.resultIndex; i < event.results.length; ++i) {
                if (event.results[i].isFinal) finalTranscript += event.results[i][0].transcript;
                else interimTranscript += event.results[i][0].transcript;
            }
            setPrompt(finalTranscript + interimTranscript);
        };

        try {
            recognition.start();
        } catch (e) {
            console.error("Failed to start recognition:", e);
            alert("Could not start speech recognition. Please refresh and try again.");
        }

    }, [isListening, prompt]);

    const handleLiveToggle = () => {
        toggleLiveSession();
    };

    useLayoutEffect(() => { resizeTextarea(); }, [prompt]);

    const handleBlur = () => { setTimeout(() => setShowCommands(false), 200); };

    // Disable input while dictating to prevent state conflicts
    const isInputDisabled = (isLoading && !isLiveSessionActive) || isListening;
    const placeholderText = isLiveSessionActive 
        ? 'Listening to conversation...' 
        : (isListening ? 'Dictating...' : 'Type a message...');

    const showStopButton = isLoading && !isLiveSessionActive && onStop;

    return (
        <footer className="flex-shrink-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-t border-slate-200 dark:border-slate-800 p-2 md:p-4 z-20 transition-all duration-300">
            <div className="max-w-3xl mx-auto relative">

                 {/* Quick Command Popover */}
                 {showCommands && (
                    <div className="absolute bottom-full left-0 mb-3 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden animate-slide-up w-64 z-30">
                        <div className="bg-slate-50 dark:bg-slate-700/50 px-3 py-2 border-b border-slate-100 dark:border-slate-700">
                             <p className="text-[10px] font-bold tracking-widest uppercase text-slate-400 dark:text-slate-500">Quick Actions</p>
                        </div>
                        <ul className="p-1">
                            {QUICK_COMMANDS.map(({ command, description, icon: Icon }) => (
                                <li key={command}>
                                    <button
                                        onClick={() => handleCommandSelect(command)}
                                        className="w-full text-left flex items-center gap-3 p-2 rounded-lg hover:bg-medical-50 dark:hover:bg-slate-700/70 transition-colors group"
                                    >
                                        <div className="text-medical-500 dark:text-medical-400">
                                            <Icon className="w-4 h-4" />
                                        </div>
                                        <div>
                                            <p className="font-mono text-xs font-bold text-slate-700 dark:text-slate-200">{command.trim()}</p>
                                            <p className="text-xs text-slate-500 dark:text-slate-400">{description}</p>
                                        </div>
                                    </button>
                                </li>
                            ))}
                        </ul>
                    </div>
                )}

                {/* File Attachment Preview */}
                 {uploadedFile && (
                    <div className="absolute bottom-full left-0 mb-3 animate-slide-up z-20">
                         <div className="relative group flex items-center gap-3 bg-white dark:bg-slate-800 p-2 pr-4 rounded-xl shadow-lg border border-slate-200 dark:border-slate-700">
                            {uploadedFile.url && uploadedFile.type.startsWith('image/') ? (
                                 <img src={uploadedFile.url} alt="Attachment" className="w-10 h-10 object-cover rounded-lg" />
                            ) : (
                                <div className="w-10 h-10 flex items-center justify-center bg-slate-100 dark:bg-slate-700 rounded-lg">
                                    <DocumentTextIcon className="w-5 h-5 text-slate-500" />
                                </div>
                            )}
                            <div className="flex flex-col">
                                <span className="text-xs font-medium text-slate-700 dark:text-slate-200 max-w-[150px] truncate">{uploadedFile.file.name}</span>
                                <span className="text-[10px] text-slate-400 uppercase">{uploadedFile.type.split('/')[1]}</span>
                            </div>
                            <button 
                                onClick={onClearFile}
                                className="ml-2 text-slate-400 hover:text-red-500 transition-colors"
                            >
                                <XCircleIcon className="w-5 h-5" />
                            </button>
                        </div>
                    </div>
                )}

                {/* Main Input Container */}
                <div className={`flex items-end gap-2 transition-all duration-300`}>

                    {/* Input Box Area */}
                    <div className={`flex-1 flex items-end gap-1 md:gap-2 p-1.5 rounded-2xl border bg-slate-50 dark:bg-slate-800/50 focus-within:bg-white dark:focus-within:bg-slate-800 focus-within:ring-2 focus-within:border-medical-500/50 focus-within:ring-medical-500/20 transition-all shadow-sm ${
                        isListening ? 'ring-2 ring-red-500/30 border-red-500/50 bg-red-50/50' : 'border-slate-200 dark:border-slate-700'
                    }`}>

                        {/* Attachment Button Group */}
                        <div className="flex items-center gap-0.5 pb-0.5 md:pb-1 pl-0.5 md:pl-1">
                            <button
                                onClick={() => fileInputRef.current?.click()}
                                disabled={isInputDisabled}
                                className="p-1.5 md:p-2 rounded-xl text-slate-400 hover:text-medical-600 hover:bg-medical-50 dark:hover:bg-slate-700 transition-all disabled:opacity-50"
                                title="Attach File"
                            >
                                <PaperclipIcon className="w-4 h-4 md:w-5 md:h-5" />
                            </button>
                             <button
                                onClick={() => cameraInputRef.current?.click()}
                                disabled={isInputDisabled}
                                className="p-1.5 md:p-2 rounded-xl text-slate-400 hover:text-medical-600 hover:bg-medical-50 dark:hover:bg-slate-700 transition-all disabled:opacity-50"
                                title="Camera"
                            >
                                <CameraIcon className="w-4 h-4 md:w-5 md:h-5" />
                            </button>
                        </div>

                        <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*,application/pdf,.txt,.md" className="hidden" />
                        <input type="file" ref={cameraInputRef} onChange={handleFileChange} accept="image/*" capture="environment" className="hidden" />

                        {/* Text Input */}
                        <textarea
                            ref={textareaRef}
                            value={prompt}
                            onChange={handleTextareaInput}
                            onKeyDown={handleKeyDown}
                            onBlur={handleBlur}
                            placeholder={placeholderText}
                            rows={1}
                            className="flex-1 bg-transparent resize-none outline-none text-slate-800 dark:text-slate-200 placeholder-slate-400 dark:placeholder-slate-500 disabled:cursor-not-allowed py-2 md:py-2.5 text-sm leading-relaxed max-h-32"
                            disabled={isInputDisabled}
                        />

                        {/* Standard Dictation Mic (Text Mode) */}
                        {currentMode !== ChatModeEnum.Live && (
                             <button
                                onClick={handleSpeechToText}
                                disabled={isLoading}
                                className={`mb-0.5 md:mb-1 p-1.5 md:p-2 rounded-xl transition-all ${
                                    isListening 
                                    ? 'text-red-500 bg-red-100 dark:bg-red-900/20 animate-pulse' 
                                    : 'text-slate-400 hover:text-medical-600 hover:bg-medical-50 dark:hover:bg-slate-700'
                                }`}
                                title={isListening ? "Stop Dictation" : "Dictate"}
                            >
                                <MicrophoneIcon className="w-4 h-4 md:w-5 md:h-5" />
                            </button>
                        )}
                    </div>

                    {/* Right Action Buttons */}
                    <div className="flex items-end gap-2">
                        {/* Live Toggle Button */}
                         <button
                            onClick={handleLiveToggle}
                            className={`h-10 w-10 md:h-[50px] md:w-[50px] rounded-2xl flex items-center justify-center transition-all duration-300 shadow-sm border ${
                                isLiveSessionActive 
                                ? 'bg-red-500 border-red-600 text-white shadow-red-500/40 animate-pulse' 
                                : currentMode === ChatModeEnum.Live 
                                    ? 'bg-white dark:bg-slate-800 border-red-200 text-red-500 hover:bg-red-50'
                                    : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-400 hover:text-slate-600 hover:border-slate-300'
                            }`}
                            title={isLiveSessionActive ? "End Live Session" : "Start Live Session"}
                        >
                            <LiveIcon className={isLiveSessionActive ? "w-5 h-5 md:w-6 md:h-6" : "w-4 h-4 md:w-5 md:h-5"} />
                        </button>

                        {/* Send or Stop Button */}
                        {(!isLiveSessionActive && currentMode !== ChatModeEnum.Live) && (
                            <button 
                                onClick={showStopButton ? onStop : handleSendClick} 
                                disabled={!showStopButton && (isInputDisabled || (!prompt.trim() && !uploadedFile))}
                                className={`h-10 w-10 md:h-[50px] md:w-[50px] rounded-2xl text-white shadow-lg transition-all duration-200 flex items-center justify-center ${
                                    showStopButton 
                                    ? 'bg-slate-700 hover:bg-slate-800 dark:bg-slate-600 dark:hover:bg-slate-500 shadow-slate-500/30' 
                                    : 'bg-medical-600 hover:bg-medical-500 hover:scale-105 active:scale-95 shadow-medical-500/30 disabled:bg-slate-300 dark:disabled:bg-slate-700 disabled:shadow-none disabled:scale-100 disabled:cursor-not-allowed'
                                }`}
                            >
                                {showStopButton ? (
                                    <StopIcon className="w-4 h-4 md:w-5 md:h-5" />
                                ) : (
                                    <SendIcon className="w-4 h-4 md:w-5 md:h-5 ml-0.5" />
                                )}
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </footer>
    );
};

export default InputBar;
